-- Generated by dbml CLI

CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email TEXT,
    display_name TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE projects (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id UUID,
    name TEXT,
    description TEXT,
    visibility VISIBILITY DEFAULT private,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    archived_at TIMESTAMPTZ,
    (owner_id, CREATED_AT),
    (visibility, CREATED_AT)
);

CREATE TABLE project_members (
    project_id UUID,
    user_id UUID,
    role PROJECT_ROLE,
    created_at TIMESTAMPTZ DEFAULT now(),
    (project_id, USER_ID) UNIQUE
);

CREATE TABLE datasets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id UUID,
    name TEXT,
    source_type DATASET_SOURCE_TYPE,
    status DATASET_STATUS DEFAULT uploading,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    archived_at TIMESTAMPTZ,
    (project_id, CREATED_AT),
    (project_id, ID) UNIQUE
);

CREATE TABLE dataset_versions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    dataset_id UUID,
    version TEXT,
    manifest JSONB DEFAULT {}'::jsonb,
    status DATASET_STATUS DEFAULT validating,
    checksum TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    (dataset_id, VERSION) UNIQUE,
    (dataset_id, CREATED_AT),
    (dataset_id, ID) UNIQUE
);

CREATE TABLE recordings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    dataset_version_id UUID,
    name TEXT,
    format RECORDING_FORMAT,
    acquisition_system ACQUISITION_SYSTEM,
    device_serial TEXT,
    manufacturer TEXT,
    duration_s DOUBLE PRECISION,
    sampling_frequency_hz DOUBLE PRECISION,
    n_channels INTEGER,
    maxfilter_sss_applied BOOLEAN DEFAULT false,
    coordinate_frame COORDINATE_FRAME DEFAULT head,
    created_at TIMESTAMPTZ DEFAULT now(),
    (dataset_version_id, CREATED_AT),
    (dataset_version_id, ID) UNIQUE
);

CREATE TABLE file_assets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    recording_id UUID,
    object_key TEXT,
    checksum TEXT,
    size_bytes BIGINT,
    media_type TEXT,
    role TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    (recording_id, ROLE)
);

CREATE TABLE channels (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    recording_id UUID,
    name TEXT,
    group_name TEXT,
    type CHANNEL_TYPE,
    unit UNIT,
    unit_mul DOUBLE PRECISION DEFAULT 1.0,
    status CHANNEL_STATUS DEFAULT good,
    coil_type TEXT,
    position_x_mm DOUBLE PRECISION,
    position_y_mm DOUBLE PRECISION,
    position_z_mm DOUBLE PRECISION,
    orientation_x DOUBLE PRECISION,
    orientation_y DOUBLE PRECISION,
    orientation_z DOUBLE PRECISION,
    opm_scalar BOOLEAN,
    opm_vector BOOLEAN,
    created_at TIMESTAMPTZ DEFAULT now(),
    (recording_id, NAME) UNIQUE,
    (recording_id, TYPE),
    (recording_id, STATUS)
);

CREATE TABLE sensor_configurations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    recording_id UUID,
    sensor_type SENSOR_TYPE,
    coordinate_frame COORDINATE_FRAME,
    positions_json JSONB DEFAULT {}'::jsonb,
    orientations_json JSONB DEFAULT {}'::jsonb,
    calibrations_json JSONB,
    movement_ref TEXT,
    time_varying BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE event_sets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    recording_id UUID,
    name TEXT,
    source TEXT,
    sample_convention TEXT,
    event_count INTEGER DEFAULT 0,
    description TEXT,
    metadata JSONB DEFAULT {}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT now(),
    (recording_id, CREATED_AT),
    (recording_id, SOURCE)
);

CREATE TABLE pipelines (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id UUID,
    name TEXT,
    description TEXT,
    status PIPELINE_STATUS DEFAULT draft,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    (project_id, CREATED_AT),
    (project_id, ID) UNIQUE
);

CREATE TABLE pipeline_versions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pipeline_id UUID,
    version TEXT,
    definition JSONB,
    image_digest TEXT,
    parameters_schema JSONB DEFAULT {}'::jsonb,
    status PIPELINE_STATUS DEFAULT draft,
    created_at TIMESTAMPTZ DEFAULT now(),
    (pipeline_id, VERSION) UNIQUE,
    (pipeline_id, CREATED_AT)
);

CREATE TABLE experiment_runs (
    id TEXT PRIMARY KEY,
    project_id UUID,
    pipeline_version_id UUID,
    dataset_version_id UUID,
    sensor_configuration_id UUID,
    initiated_by UUID,
    status RUN_STATUS DEFAULT queued,
    parameters JSONB DEFAULT {}'::jsonb,
    idempotency_key TEXT,
    error_classification TEXT,
    cpu_limit_cores DOUBLE PRECISION,
    memory_limit_bytes BIGINT,
    disk_limit_bytes BIGINT,
    wall_clock_limit_s INTEGER,
    started_at TIMESTAMPTZ,
    finished_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now(),
    (status, CREATED_AT),
    (dataset_version_id, CREATED_AT),
    (pipeline_version_id, CREATED_AT),
    (project_id, CREATED_AT)
);

CREATE TABLE artifacts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    run_id TEXT,
    object_key TEXT,
    checksum TEXT,
    size_bytes BIGINT,
    media_type TEXT,
    kind ARTIFACT_KIND DEFAULT derived,
    metadata JSONB DEFAULT {}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT now(),
    (run_id, KIND)
);

CREATE TABLE usage_records (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID,
    run_id TEXT,
    resource_type RESOURCE_TYPE,
    quantity BIGINT,
    created_at TIMESTAMPTZ DEFAULT now(),
    (user_id, CREATED_AT),
    (resource_type, CREATED_AT)
);

CREATE TABLE audit_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    actor_id UUID,
    action TEXT,
    resource_type TEXT,
    resource_id TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    (resource_type, RESOURCE_ID,,
    (actor_id, CREATED_AT)
);

CREATE TABLE outbox_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    topic TEXT,
    payload JSONB,
    status OUTBOX_STATUS DEFAULT pending,
    attempts INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT now(),
    published_at TIMESTAMPTZ,
    (status, CREATED_AT),
    (topic, CREATED_AT)
);

CREATE TABLE auth_credentials (
    user_id UUID PRIMARY KEY,
    email TEXT,
    password_hash TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID,
    token_hash TEXT,
    user_agent TEXT,
    ip_address TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    expires_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ
);

CREATE TABLE password_reset_tokens (
    token_hash TEXT PRIMARY KEY,
    user_id UUID,
    expires_at TIMESTAMPTZ,
    used_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE upload_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    dataset_id UUID,
    project_id UUID,
    status TEXT DEFAULT 'pending',
    expected_size_bytes BIGINT,
    checksum_sha256 TEXT,
    declared_format TEXT,
    acquisition_system TEXT,
    expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now(),
    completed_at TIMESTAMPTZ
);

CREATE TABLE upload_targets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    upload_session_id UUID,
    name TEXT,
    object_key TEXT,
    size_bytes BIGINT,
    checksum_sha256 TEXT,
    media_type TEXT,
    role TEXT,
    uploaded_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now(),
    (upload_session_id, OBJECT_KEY) UNIQUE
);

CREATE TABLE run_logs (
    run_id TEXT,
    sequence BIGINT,
    timestamp TIMESTAMPTZ DEFAULT now(),
    level TEXT,
    source TEXT,
    message TEXT,
    (run_id, SEQUENCE) PRIMARY KEY
);

CREATE TABLE shares (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id UUID,
    resource_id UUID,
    scope TEXT,
    role TEXT,
    token_hash TEXT,
    created_by UUID,
    expires_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE idempotency_keys (
    key TEXT,
    user_id UUID,
    request_hash TEXT,
    response_status INTEGER,
    response_body JSONB,
    created_at TIMESTAMPTZ DEFAULT now(),
    expires_at TIMESTAMPTZ,
    (key, USER_ID) PRIMARY KEY
);

